  },
  {
    "statement": "A study in Indonesia found that using noise deterrents along with tree nets reduced orangutan crop raiding.",
    "citations": []
  },
  {
    "statement": "A study in the Democratic Republic of Congo found that chasing gorillas with random noise resulted in the gorillas returning from plantations to areas near protected forest.",
    "citations": []
  },
  {
    "statement": "There is currently no evidence available for the effectiveness of using bright lights to deter primate crop-raiding.",
    "citations": []
  },
  {
    "statement": "No studies were found that directly and quantitatively tested bright lights as a deterrent method for primate crop-raiding.",
    "citations": []
  },
