[
  {
    "statement": "The evidence base for conservation actions designed to mitigate the impacts of commercial logging on primate populations shows mixed results.",
    "citations": []
  },
  {
    "statement": "A site comparison in Sierra Leone found that primate densities were higher in a forest that had been logged at a low intensity than in a forest logged at a high intensity.",
    "citations": [
      "1485"
    ]
  },
  {
    "statement": "A before-and-after study in Madagascar found that the number of lemurs increased following selective logging.",
    "citations": [
      "1485"
    ]
  },
  {
    "statement": "A site comparison study in Uganda found that primate densities were similar in a forest that had been logged at a low intensity and a forest logged at a high intensity.",
    "citations": [
      "1485"
    ]
  },
  {
    "statement": "A site comparison study in the Democratic Republic of Congo found that community control was more effective at reducing illegal bushmeat hunting, including primates, compared to a nearby national park.",
    "citations": [
      "1482"
    ]
  },
  {
    "statement": "A before-and-after study in Cameroon found that no incidents of gorilla poaching occurred over three years after the implementation of community control and monitoring of illegal activities.",
    "citations": [
      "1482"
    ]
  },
  {
    "statement": "A site comparison study in Nigeria found that there were more gorillas and chimpanzees in an area managed by a community conservation organisation than in areas not managed by local communities.",
