  },
  {
    "statement": "No evidence was found for the effectiveness of providing domestic meat to logging workers to reduce hunting.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of closing non-essential roads after logging operations.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of reducing forestry team sizes.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of certifying forest concessions as primate friendly.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of implementing road blocks to inspect cars for illegal primate bushmeat.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of avoiding the slashing of specific vegetation types.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of implementing small and dispersed logging compartments.",
    "citations": []
  }
