[
  {
    "statement": "Tourism projects focused on wild primates have both documented benefits and harms.",
    "citations": []
  },
  {
    "statement": "Populations of mountain gorillas in Rwanda, Uganda, and the Republic of Congo increased by 168% over 41 years after tourism projects were initiated with continuous monitoring and other interventions.",
    "citations": []
  },
  {
    "statement": "In Rwanda, the number of immature mountain gorillas increased by 22% after a tourism project was initiated with other interventions.",
    "citations": []
  },
  {
    "statement": "In Rwanda, snares declined by 30% after a tourism project was initiated with other interventions.",
    "citations": []
  },
  {
    "statement": "Black howler monkeys in Belize increased by 138% over 13 years after a tourism project was implemented with other interventions.",
    "citations": []
  },
  {
    "statement": "An intensive tourism project for Tibetan macaques in China that included food provisioning and range restrictions increased the macaques' stress levels.",
    "citations": []
  },
  {
    "statement": "An intensive tourism project for Tibetan macaques in China resulted in infant mortality reaching 100% in some years.",
    "citations": []
  },
  {
    "statement": "A tourism project in Madagascar resulted in population size and body/group size declines for two lemur species.",
    "citations": []
  },
  {
    "statement": "A tourism project in Madagascar resulted in an increase for one lemur species.",
    "citations": []
  },
  {
    "statement": "A feeding ban for Japanese macaques led to population declines in size and productivity.",
    "citations": []
  }
]

[
  {
    "statement": "The reintroduction of primates into habitats where the same species is already present shows mixed survival outcomes.",
    "citations": []
  },
  {
    "statement": "The majority of reintroduced chimpanzees in four studies in Guinea and the Republic of Congo survived for at least one to five years when released into habitat with existing chimpanzee populations.",
    "citations": []
  },
  {
    "statement": "One study in Malaysia found that a majority of orangutans survived reintroduction.",
    "citations": []
  },
  {
    "statement": "Another controlled study found that a reintroduced orangutan population declined 33 years after release.",
    "citations": []
  },
  {
    "statement": "In Belize, primate populations increased five years after reintroduction into habitat with existing species.",
    "citations": []
  },
  {
    "statement": "In Thailand, primate populations declined post-reintroduction.",
    "citations": []
  },
  {
    "statement": "Sixteen studies across Brazil, French Guiana, Indonesia, Madagascar, South Africa, and other locations showed variable survival rates for reintroduced primates.",
    "citations": []
  },
  {
    "statement": "Some studies found a majority of reintroduced primates survived for 2-12 months.",
    "citations": []
  },
  {
    "statement": "Other studies found a minority of reintroduced primates survived for 15 weeks to 7 years.",
    "citations": []
  },
  {
    "statement": "Two controlled studies in Madagascar and Indonesia found that reintroduced primates had similar diets to wild individuals after release into habitats with existing populations.",
    "citations": []
  },
  {
    "statement": "Two controlled studies in Madagascar and Indonesia found that reintroduced primates had similar behaviors to wild individuals after release into habitats with existing populations.",
    "citations": []
  }
]

[
  {
    "statement": "Translocated primate populations have been observed to survive for varying lengths of time post-release.",
